export type OrderConfirmationParams = {
  orderNumber: string;
  items: {
    name: string;
    quantity: number;
    price: number;
  }[];
  couponCode?: string;
  total: number;
};

export type Locale = "en" | "fr" | "es";

export interface RenderOptions {
  /**
   * The locale to render in. Anything is accepted -- a user preference, an
   * Accept-Language value -- and resolved to the closest built locale, falling
   * back to the default. The result's `locale` says which one was used.
   */
  locale?: Locale | (string & {});
  /** IANA time zone for dates, e.g. "America/Montreal". */
  timeZone?: string;
}

export declare function renderOrderConfirmation(
  params: OrderConfirmationParams,
  options?: RenderOptions
): {
  name: "order-confirmation";
  locale: Locale;
  subject: string;
  sender: "orders@mailgrail.com";
  html: string;
  text: string;
};

